const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{chromium,webkit}=require('playwright');const engine=process.env.NECK_BROWSER||'chromium',out=path.resolve('qa-output',engine);fs.mkdirSync(out,{recursive:true});
(async()=>{const browser=await({chromium,webkit}[engine]).launch(engine==='chromium'?{headless:true,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']}:{headless:true});const page=await browser.newPage({viewport:{width:960,height:960},deviceScaleFactor:1}),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:8765/qa/');await page.waitForFunction(()=>window.__ready);const rows=[];
for(const age of['young','child','old'])for(const stage of['final','cotangent'])for(const material of['gray','skin','normal'])for(const view of['rear3q','rearLeft']){const config={age,stage,material,view},r=await page.evaluate(c=>window.neckDiagnostic.show(c),config);assert.equal(r.glError,0);assert.equal(r.vertexCount,25417);assert.equal(r.triangles,50624);await page.screenshot({path:path.join(out,`${age}-${stage}-${material}-${view}.png`)});rows.push(r);}
for(const stage of['raw','contour','final','uniform','cotangent']){const r=await page.evaluate(stage=>window.neckDiagnostic.show({stage,age:'young',material:'gray',view:'side',rake:true}),stage);await page.screenshot({path:path.join(out,`young-${stage}-gray-side-rake.png`)});rows.push(r);}
assert.deepEqual(errors,[]);fs.writeFileSync(path.join(out,'render-report.json'),JSON.stringify({passed:true,engine,version:browser.version(),sourceCommit:'cdf2ac931e444875dd400eafada7ee118702147f',actualWebGL:true,originalSkinShader:true,sourceSkinCoordinatesFixed:true,diagnosticNotProductionIntegration:true,rows,errors},null,2));await browser.close();})().catch(e=>{console.error(e);process.exit(1)});
